// Extract declarative host tables from the compiled reference; Rust executes all behavior.
import fs from "node:fs";
import vm from "node:vm";
import {pathToFileURL} from "node:url";
const source=fs.readFileSync(process.argv[2],"utf8");
const base=new URL(".",pathToFileURL(process.argv[2]));
const {JOURNEY_PROMPTS}=await import(new URL("journeys.js",base));
const {LIVE_UNAVAILABLE_CAPABILITIES}=await import(new URL("live.js",base));
const context=vm.createContext({JOURNEY_PROMPTS,LIVE_UNAVAILABLE_CAPABILITIES});
const text=source.slice(source.indexOf("const resources ="),source.indexOf("function isObject(")).replace(/^export .*;$/gm,"");
vm.runInContext(text,context);
const get=name=>vm.runInContext(name,context);
const data=Object.fromEntries(["resources","prompts","safetyResource","hostUnavailableCapabilities","unavailableCapabilities","liveResource","liveWorkflowResource"].map(name=>[name,get(name)]));
const literal=regexp=>{const match=source.match(regexp);if(!match)throw Error("missing table "+regexp);return vm.runInNewContext("("+match[1]+")");};
data.asyncOnlyTools=literal(/const ASYNC_ONLY_TOOLS = new Set\((\[[\s\S]*?\])\);/);
data.asyncHandledTools=literal(/if \(!(\[[^\n]+\])\.includes\(name\) && !ASYNC_ONLY_TOOLS/);
data.syncAsyncRequiredTools=literal(/if \((\[[^\n]+\])\.includes\(params.name\) \|\| ASYNC_ONLY_TOOLS/);
data.argumentTools=literal(/const argumentTools = new Set\((\[[\s\S]*?\])\);/);
data.transactionOwnerPrefixes=literal(/const byPrefix = (\{[\s\S]*?\});/);
data.transactionOwnerKinds=literal(/const byKind = (\{[\s\S]*?\});/);
fs.writeFileSync(new URL("../../src/host/data.json",import.meta.url),JSON.stringify(data));
